discrete MotorControlSystem
port:
    event input real M;  // Start the signal.
event input real S;  // Stop the signal.
event input real F;  // Fault detection signal.
event input real R;  // Reset Signal
event input real T;  // Restart the signal.
event output real PowerRequest;  // Power request
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(M) then
            transition(State2);
        end;
    end;

    state State2
        when receive(S) then
            transition(State1);
        end;
        when receive(F) then
            transition(State3);
        end;
    end;

    state State3
        when receive(R) then
            transition(State1);
        end;
        when receive(T) then
            transition(State2);
        end;
    end;
end;
end;

discrete SignalProcessingSystem
port:
    event input real N;  // New signal.
event input real I;  // Break signal.
event input real E;  // Restore signal.
event output real PowerRequest;  // Power request
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(N) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State1);
        end;
        when receive(I) then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State1);
        end;
        when receive(E) then
            transition(State2);
        end;
    end;
end;
end;

discrete PowerManagementSystem
port:
    event input real P;  // Power stabilizer signal.
event input real A;  // Power anomaly signal.
event input real O;  // Turn off the signal.
event input real R;  // Reset Signal
event input real U;  // Re-enact the telecommunications.
event output real PowerStatus;  // Power State
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(P) then
            transition(State2);
            out
                send(PowerStatus, 1);
        end;
    end;

    state State2
        when receive(A) then
            transition(State3);
            out
                send(PowerStatus, 0);
        end;
        when receive(O) then
            transition(State4);
            out
                send(PowerStatus, 0);
        end;
    end;

    state State3
        when receive(P) then
            transition(State2);
            out
                send(PowerStatus, 1);
        end;
        when receive(R) then
            transition(State1);
            out
                send(PowerStatus, 0);
        end;
    end;

    state State4
        when receive(U) then
            transition(State1);
            out
                send(PowerStatus, 1);
        end;
    end;
end;
end;

